style.css:
@-moz-document domain("roblox.com") {
/* ============================= */
/*   GLOBAL RESET & BACKGROUND   */
/* ============================= */

html, body {
  height: 100% !important;
  background: transparent !important;
  overflow-x: hidden !important;
  font-family: "Segoe UI", system-ui, sans-serif !important;
}

/* Put your wallpaper directly on body */
body {
  background-image: url("https://images3.alphacoders.com/788/788720.jpg") !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-position: center center !important;
  background-attachment: fixed !important;
  animation: bgPan 40s linear infinite alternate !important;
}

/* Slow pan animation */
@keyframes bgPan {
  0%   { background-position: 50% 50%; }
  100% { background-position: 60% 55%; }
}

/* Kill Roblox's big gradient pseudo element on classic site */
body.rbx-body::before,
body.rbx-body::after,
.rbx-body::before,
.rbx-body::after {
  content: none !important;
  background: none !important;
  box-shadow: none !important;
}

/* Kill extra gradient wrappers on newer layouts (harmless on old layout) */
.theme-background,
.theme-base,
.theme-dark,
.theme-light,
.theme-provider,
.app-container,
.root-container,
.dark-theme,
.light-theme,
.app,
#root > div,
body > div,
body > div > div {
  background: transparent !important;
  backdrop-filter: none !important;
}

/* ============================= */
/*          GLASS PANELS         */
/* ============================= */

#container,
.container,
.content,
#rbx-body,
#app,
.ng-scope,
.rbx-body-content,
.rbx-page,
.rbx-page-content {
  background: rgba(5, 5, 20, 0.78) !important;
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border-radius: 14px;
  border: 1px solid rgba(120, 220, 255, 0.18);
  box-shadow:
    0 0 18px rgba(0, 0, 0, 0.75),
    0 0 35px rgba(0, 200, 255, 0.2);
}

/* Strip random solid backgrounds */
.section-content,
.section,
.panel,
.panel-default,
.rbx-upgrade-now-banner {
  background: transparent !important;
  box-shadow: none !important;
}


/* ============================= */
/*        HEADER / NAVBAR        */
/* ============================= */

header,
#navigation-container,
.rbx-navbar,
.rbx-header,
.navbar {
  background: linear-gradient(90deg,
              rgba(0, 0, 0, 0.75),
              rgba(0, 40, 80, 0.9)) !important;
  border-bottom: 1px solid rgba(120, 220, 255, 0.35) !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.8);
}

.navbar a,
.rbx-navbar a,
.rbx-navigation-item a,
.rbx-header a {
  color: #e5f7ff !important;
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.8);
  transition: color 0.2s ease, text-shadow 0.2s ease, transform 0.2s ease;
}

.navbar a:hover,
.rbx-navbar a:hover,
.rbx-navigation-item a:hover,
.rbx-header a:hover {
  color: #7bf5ff !important;
  text-shadow:
    0 0 6px rgba(0, 255, 255, 0.8),
    0 0 13px rgba(120, 220, 255, 0.8);
  transform: translateY(-1px);
}


/* ============================= */
/*         TITLES / TEXT         */
/* ============================= */

h1, h2, h3, h4, .text-lead {
  color: #f5fcff !important;
  letter-spacing: 0.03em;
  text-shadow:
    0 0 4px rgba(0, 0, 0, 0.7),
    0 0 14px rgba(0, 255, 255, 0.24);
}

p, span, li, .text, .small, .label, .form-label {
  color: #d5e6ff !important;
}

.text-subheader, .stat, .currency, .robux-text {
  color: #7cf8ff !important;
}


/* ============================= */
/*           BUTTONS             */
/* ============================= */

.btn-primary,
.btn-growth-xs,
.btn-growth-sm,
.btn-common-play-game,
.btn-primary-md {
  background: linear-gradient(135deg, #00d4ff, #00ffa8) !important;
  border: none !important;
  color: #041013 !important;
  text-shadow: none !important;
  border-radius: 999px !important;
  box-shadow:
    0 0 12px rgba(0, 255, 255, 0.7),
    0 0 24px rgba(0, 180, 255, 0.5);
  transform: translateY(0);
  transition:
    transform 0.15s ease-out,
    box-shadow 0.15s ease-out,
    filter 0.15s ease-out;
}

.btn-primary:hover,
.btn-growth-xs:hover,
.btn-growth-sm:hover,
.btn-common-play-game:hover,
.btn-primary-md:hover {
  transform: translateY(-2px) scale(1.03);
  box-shadow:
    0 0 18px rgba(0, 255, 255, 0.9),
    0 0 36px rgba(0, 180, 255, 0.7);
  filter: brightness(1.08);
}

.btn-secondary,
.btn-control-md,
.btn-secondary-md {
  background: rgba(5, 20, 40, 0.9) !important;
  color: #cde8ff !important;
  border-radius: 999px !important;
  border: 1px solid rgba(120, 220, 255, 0.4) !important;
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.btn-secondary:hover,
.btn-control-md:hover,
.btn-secondary-md:hover {
  background: rgba(17, 40, 80, 0.95) !important;
  box-shadow: 0 0 14px rgba(0, 200, 255, 0.45);
  transform: translateY(-1px);
}

/* Play button breathing glow */
.btn-common-play-game {
  animation: playPulse 1.8s ease-in-out infinite;
}

@keyframes playPulse {
  0%, 100% {
    transform: translateY(0) scale(1);
    box-shadow:
      0 0 10px rgba(0, 255, 200, 0.4),
      0 0 20px rgba(0, 180, 255, 0.4);
  }
  50% {
    transform: translateY(-2px) scale(1.05);
    box-shadow:
      0 0 16px rgba(0, 255, 200, 0.9),
      0 0 32px rgba(0, 180, 255, 0.8);
  }
}


/* ============================= */
/*       GAME CARDS / TILES      */
/* ============================= */

.game-card,
.game-card-container,
.game-card-thumb-container,
.game-card-info,
.thumbnail-2d-container,
.game-card-link {
  background: rgba(5, 10, 30, 0.8) !important;
  border-radius: 16px !important;
  border: 1px solid rgba(120, 220, 255, 0.25) !important;
  overflow: hidden;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.game-card:hover,
.game-card-container:hover,
.game-card-link:hover {
  transform: translateY(-4px) scale(1.015);
  box-shadow:
    0 12px 24px rgba(0, 0, 0, 0.9),
    0 0 18px rgba(0, 230, 255, 0.6);
  border-color: rgba(120, 220, 255, 0.7) !important;
}

.game-card-thumb-container img,
.thumbnail-2d-container img {
  transition: transform 0.4s ease, filter 0.4s ease;
}

.game-card:hover img,
.thumbnail-2d-container:hover img {
  transform: scale(1.05);
  filter: brightness(1.07) saturate(1.15);
}


/* ============================= */
/*         SCROLLBARS            */
/* ============================= */

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: rgba(2, 8, 20, 0.9);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #00d4ff, #ff00c3);
  border-radius: 999px;
  border: 2px solid rgba(2, 8, 20, 0.9);
}

::-webkit-scrollbar-thumb:hover {
  filter: brightness(1.1);
}


/* ============================= */
/*       INPUTS & SEARCH         */
/* ============================= */

input[type="text"],
input[type="search"],
input[type="password"],
textarea,
.form-control {
  background: rgba(3, 8, 25, 0.9) !important;
  color: #d9f0ff !important;
  border-radius: 999px !important;
  border: 1px solid rgba(120, 220, 255, 0.4) !important;
  box-shadow: 0 0 0 transparent;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease;
}

input:focus,
textarea:focus,
.form-control:focus {
  outline: none !important;
  border-color: #00f0ff !important;
  background: rgba(5, 15, 40, 0.94) !important;
  box-shadow: 0 0 10px rgba(0, 255, 255, 0.7);
}


/* ============================= */
/*           CLEANUP             */
/* ============================= */

a {
  color: #8de7ff !important;
  transition: color 0.2s ease, text-shadow 0.2s ease;
}

a:hover {
  color: #ffffff !important;
  text-shadow: 0 0 8px rgba(120, 220, 255, 0.8);
}
}
